   {"id":"s1e05-86","sistema":"ep","clip":"clip/s1e05-86.mp3","yt":"qqllJti6l94","da":86.12,"durata":41.48,"onda":[5,7,6,4,0,4,7,8,5,5,7,4,3,8,7,6,7,6,6,5,8,4,8,6,5,7,7,5,5,6,4,5,6,7,3,1,1,6,9,6,4,9,7,5,6,8,9,6,7,6,7,6,6,6,7,5,5,4,4,4,4,8,8,7,7,6,0,6,8,8,6,5,5,2,5,5,5,5,6,4,1,4,5,4,7,8,7,7,2,1,8,7,3,5,6,5,5,6,4,6,6,5,6,6,5,0,5,5,5,4],"sottotitoli":[[0,2.25,"Per quanto mi riguarda,"],[2.2,4.85,"su come io l’ho vissuto sulla mia pelle,"],[4.8,10.03,"diciamo che il primo effetto negativo è stato in relazione all’aver"],[9.98,13.4,"trovato un sistema che spiega tutto."],[14.13,18.67,"Un sistema che mette tutto in ordine, un sistema che dà le risposte"],[18.62,23.21,"a domande che io avevo dentro ma che neanche sapevo di avere."],[23.16,25.17,"E tutto questo mi ha portato"],[25.86,31.95,"ben presto, diciamo nel primo anno, primi due anni,"],[31.9,34.05,"a una sorta di..."],[34.0,41.48,"Adorazione verso questo sistema, una sorta di idolatria del simbolo."]]},
   {"id":"s1e05-1655","sistema":"ep","clip":"clip/s1e05-1655.mp3","yt":"qqllJti6l94","da":1654.99,"durata":43.28,"onda":[5,6,5,4,7,1,1,6,5,6,6,3,4,7,4,2,6,7,6,3,6,7,6,5,4,6,5,5,6,5,4,4,5,3,2,2,1,5,6,6,6,5,5,4,4,3,7,7,2,3,4,4,6,7,4,5,5,6,6,5,4,4,5,4,5,2,6,2,6,7,5,7,6,5,4,4,5,5,5,4,4,3,1,7,9,4,5,5,3,5,5,3,4,0,0,7,5,6,4,5,5,4,3,1,6,7,6,4,3,2],"sottotitoli":[[0,2.9,"L’Enneagramma ha in sé"],[2.85,6.57,"dei sistemi, diciamo, suoi."],[6.52,11.72,"Di backup, per cui noi più di tanti danni con l’Enneagramma o con"],[11.67,14.82,"un utilizzo sbagliato, noi non possiamo farli."],[14.77,18.04,"Questa è una cosa che ho visto e imparato negli anni,"],[17.99,21.42,"per cui, anche per chi ci sta ascoltando,"],[21.37,26.13,"diciamo che è normale farsi entusiasmare da questo sistema,"],[26.08,29.51,"ma è anche normale utilizzarlo attraverso il filtro,"],[29.46,32.73,"le distorsioni che il nostro tipo ha."],[32.68,34.43,"Per cui"],[34.38,37.56,"va da sé che"],[37.51,41.3,"lo utilizzeremo male nel momento che lo conosciamo."],[41.25,43.28,"E questo però non deve scoraggiarci."]]}
